const originalPicnicImages={"laptop": "data:image/gif;base64,", "camera": "/assets/cam.png", "phone": "/assets/phone.png"};(()=>{if(companionMode)return;for(const [id,src]of Object.entries(originalPicnicImages)){const img=document.createElement('img');img.src=src;img.alt=id;img.className='original-scene-prop';document.getElementById(id).append(img);}const root=document.documentElement,sun=document.querySelector('#sun>img');function sync(){const original=root.dataset.picnicBackground==='picnic';sun.src=original?'/assets/sunshine.png':'/assets/sunshine-cute.gif';document.getElementById('sun').classList.toggle('original-sun',original);dispatchEvent(new Event('picnic-scene-sky-reset'));}new MutationObserver(sync).observe(root,{attributes:true,attributeFilter:['data-picnic-background']});sync();})();